import{af as t,z as a,J as i,ab as o}from"./chunks/framework.C9-KCiTM.js";const p=JSON.parse('{"title":"How do I reactivate my Lightbug devices","description":"","frontmatter":{},"headers":[],"relativePath":"guides/reactivate-devices.md","filePath":"guides/reactivate-devices.md"}'),r={name:"guides/reactivate-devices.md"};function l(c,e,s,n,d,u){return a(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793272434000"},[...e[0]||(e[0]=[o('<h1 id="how-do-i-reactivate-my-lightbug-devices" tabindex="-1">How do I reactivate my Lightbug devices <a class="header-anchor" href="#how-do-i-reactivate-my-lightbug-devices" aria-label="Permalink to &quot;How do I reactivate my Lightbug devices&quot;">​</a></h1><p>If you have deactivated your device (cancelled your subscription), you can reactivate it at any time from the Lightbug App, just follow the simple steps below:</p><ol><li>Open the Lightbug App or go to the Web Portal (<a href="https://lightbug.cloud/" target="_blank" rel="noreferrer">https://lightbug.cloud/</a>)</li><li>Go to &#39;Settings&#39;, then to the &#39;Data Plan&#39; page</li><li>In the &#39;Devices&#39; section, find the tracker you would like to reactivate, and click &#39;activate&#39;</li><li>The pop up box will show you a selection of billing plans that you can pick from. Select a plan for the device.</li></ol><p>For an overview of the available plan tiers, see <a href="/docs/pr/34/terminology/plans">Plans</a>.</p><p>(<a href="https://account.lightbug.cloud/" target="_blank" rel="noreferrer">https://account.lightbug.cloud/</a>) Your device is now reactivated and ready to use!<br> If you want to update the settings, we recommend referring to our User Manual (<a href="https://lightbug.io/user_manual.pdf" target="_blank" rel="noreferrer">https://lightbug.io/user_manual.pdf</a>).</p><p>Still need assistance, please reach out to us (<a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">https://lightbug.io/contact/</a>).</p>',6)])])}